  function slugifyWithSep(str, sep) {
    let s = OT.slugifyVi(str);
    if (sep === "_") s = s.replace(/-/g, "_");
    return s;
  }

  async function shaHexBytes(algo, bytes) {
    return OTDevCrypto.digestBytes(algo, bytes);
  }

  function parseTimestampInput(raw) {
    const s = String(raw || "").trim();
    if (!s) throw new Error("Enter a Unix timestamp or an ISO date string.");
    if (/^\d+$/.test(s)) {
      const n = Number(s);
      if (!Number.isFinite(n)) throw new Error("Invalid timestamp.");
      const ms = s.length >= 13 ? n : n * 1000;
      const d = new Date(ms);
      if (Number.isNaN(d.getTime())) throw new Error("Timestamp is out of range.");
      return d;
    }
    const d = new Date(s);
    if (Number.isNaN(d.getTime())) throw new Error("Couldn't parse the date — try Unix (seconds/ms) or ISO 8601.");
    return d;
  }

  function formatTimestampBlock(d) {
    const ms = d.getTime();
    const sec = Math.floor(ms / 1000);
    return [
      "Unix (seconds):  " + sec,
      "Unix (ms):    " + ms,
      "ISO 8601:     " + d.toISOString(),
      "Local (vi-VN): " + d.toLocaleString("vi-VN", { hour12: false })
    ].join("\n");
  }

  function generateUuids(count) {
    const n = Math.min(50, Math.max(1, Number(count) || 1));
    const out = [];
    for (let i = 0; i < n; i++) out.push(OTDevCrypto.randomUUIDv4());
    return out.join("\n");
  }

